<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';
import {api,formatDate,type Note} from '../client';
const items=ref<Note[]>([]),query=ref(''),error=ref(''),loading=ref(true),offset=ref(0);let controller:AbortController|undefined;
async function load(search=false){controller?.abort();controller=new AbortController();loading.value=true;error.value='';try{const result=await api<{items:Note[]}>(search&&query.value?'/api/search?q='+encodeURIComponent(query.value):'/api/posts?offset='+offset.value,{signal:controller.signal});items.value=result.items;}catch(e){if((e as Error).name!=='AbortError')error.value=(e as Error).message;}finally{loading.value=false;}}
onMounted(()=>load());onBeforeUnmount(()=>controller?.abort());
</script>
<template><main class="public-page research-page"><div class="eyebrow">PUBLIC / MEMBER RESEARCH</div><div class="page-heading"><div><h1>Research, shared deliberately.</h1><p>Public notes from Meridian members. These are author views, not verified investment recommendations.</p></div><RouterLink class="button" to="/app/notes">Write a note ↗</RouterLink></div><form class="search-row" @submit.prevent="offset=0;load(true)"><label for="research-search">Search public notes</label><input id="research-search" v-model="query" placeholder="A question, topic or keyword" maxlength="100"><button class="primary">Search</button></form><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="loading" class="empty">Loading research…</p><section v-else class="research-list"><article v-for="note in items" :key="note.id"><div class="research-meta"><span>MEMBER NOTE</span><time>{{formatDate(note.updated_at)}}</time></div><RouterLink :to="'/research/'+note.id"><h2>{{note.title}}</h2></RouterLink><p>{{note.body}}</p><small>{{note.author}}</small></article><p v-if="!items.length&&!error" class="empty">No public notes yet. Private notes stay in their authors’ workspaces.</p></section><div v-if="!query" class="pager"><button :disabled="offset===0" @click="offset=Math.max(0,offset-25);load()">Previous</button><button :disabled="items.length<25" @click="offset+=25;load()">Next</button></div></main></template>
